const map = blk: {
    @setEvalBranchQuota(100_000);
    var kvs: [list.len]struct { []const u8, Msg } = undefined;
    for (list, 0..) |e, i| kvs[i] = .{ e.name, e.doc };
    break :blk std.StaticStringMap(Msg).initComptime(kvs);
};

/// What value `name` does; null: the port does not read it (only the exe does).
pub fn get(name: []const u8) ?Msg {
    return map.get(name);
}

test "no name twice, every one described in both languages" {
    try std.testing.expectEqual(list.len, map.kvs.len);
    for (list) |e| try std.testing.expect(e.doc.en.len > 0 and e.doc.ru.len > 0);
}
